function level(i){const length=3600+i*450,platforms=[],gaps=[];const step=460-i*25,gap=70+[0,6,18,30,42][i];for(let x=670;x<length-400;x+=step)gaps.push([x,x+gap]);let x=0;for(const [a,b]of gaps){platforms.push({x,y:470,w:a-x,h:100,ground:true});x=b}platforms.push({x,y:470,w:length-x,h:100,ground:true});for(let n=0;n<8+i;n++){const px=390+n*(310-i*10);platforms.push({x:px,y:365-(n%3)*35,w:140-i*7,h:25,baseX:px,moving:i>=2&&n%3===1,phase:n})}const coins=[];for(let n=0;n<40+i*6;n++){const cx=220+n*(length-400)/(40+i*6);if(!gaps.some(([a,b])=>cx>a-10&&cx<b+10))coins.push({x:cx,y:420,taken:false})}platforms.filter(p=>!p.ground).forEach(p=>coins.push({x:p.x+p.w/2,y:p.y-40,taken:false}));const enemies=[];for(let n=0;n<4+i*2;n++){let ex=650+n*(length-950)/(4+i*2);const floor=platforms.find(p=>p.ground&&ex>p.x+40&&ex<p.x+p.w-40);if(floor){ex=clamp(ex,floor.x+100,floor.x+floor.w-100);enemies.push({x:ex,y:440,vx:(n%2?1:-1)*(36+i*12),min:Math.max(floor.x+95,ex-45),max:Math.min(floor.x+floor.w-95,ex+45),alive:true})}}return{length,platforms,gaps,coins,enemies,flag:Math.floor(length/2)-100,goal:length-130}}
